"""Regenerates src/main/resources/assets/cubecraft/textures/sky/*.png  (python3 generate.py)"""
import os, json, numpy as np
from PIL import Image
from skygen import *
from presets import PRESETS, ORDER

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "..", "src", "main", "resources",
                   "assets", "cubecraft", "textures", "sky")
NS, SS = 640, 1536
os.makedirs(OUT, exist_ok=True)

def save(img, path, mode):
    Image.fromarray(img, mode).save(path, optimize=True, compress_level=9)
    # .mcmeta files are generated by build.gradle (processResources), not stored in git

import sys
what = sys.argv[1:] or ["stars"] + ORDER
if "stars" in what:
    for f, img in star_layer(SS).items():
        save(img, f"{OUT}/stars_{f}.png", "RGBA")
    print("stars done", flush=True)
for p in [w for w in what if w != "stars"]:
    P = PRESETS[p]; cal = calibrate(P)
    faces = {}
    for i, f in enumerate(FACES):
        faces[f] = nebula_face(i, NS, P, cal)
        save(faces[f], f"{OUT}/{p}_{f}.png", "RGB")
    az = np.linspace(0, 2 * np.pi, 360, endpoint=False)
    col = []
    for e in (0.0, 0.08):
        d = np.stack([np.cos(az) * np.cos(e), np.full_like(az, np.sin(e)), np.sin(az) * np.cos(e)], -1).astype(np.float32)
        col.append(sample_cube(faces, d).mean(0))
    c = np.mean(col, 0) * 0.75  # a little darker so fog does not glow
    print(p, "horizon 0x%02X%02X%02X" % tuple(int(x * 255) for x in c), flush=True)
save(np.full((4, 4, 4), 255, dtype=np.uint8), f"{OUT}/white.png", "RGBA")
print("done")
